var a=260;var i=[{id:`cooking-260-01`,theoryId:260,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why does rapid freezing often better preserve the texture of fruit?`,ua:`Чому швидке заморожування часто краще зберігає текстуру фруктів?`},explanation:{en:`Large crystals can rupture cells and increase drip upon thawing.`,ua:`Великі кристали можуть руйнувати клітини й збільшувати втрату соку після розморожування.`},options:[{id:`a`,text:{en:`It converts food into shelf-stable canned goods`,ua:`Перетворює їжу на консерви кімнатного зберігання`}},{id:`b`,text:{en:`It always removes all microorganisms`,ua:`Завжди видаляє всі мікроорганізми`}},{id:`c`,text:{en:`It tends to produce smaller ice crystals and less cell damage`,ua:`Зазвичай утворює дрібніші кристали льоду й менше ушкоджує клітини`}}],answer:{optionIds:[`c`]}},{id:`cooking-260-02`,theoryId:260,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Freezing at household freezer temperatures reliably sterilizes contaminated food.`,ua:`Заморожування за температур побутової морозильної камери надійно стерилізує забруднені продукти.`},explanation:{en:`Many microbes survive freezing and can grow after thawing if food is mishandled.`,ua:`Багато мікроорганізмів переживають заморожування й можуть розмножуватися після розморожування за неправильного поводження.`},answer:{value:!1}},{id:`cooking-260-03`,theoryId:260,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match freeze-related terms to consequences.`,ua:`Поєднайте поняття заморожування з наслідками.`},explanation:{en:`Freezing quality depends on the entire temperature and storage history.`,ua:`Якість заморожування залежить від усієї історії температури та зберігання.`},leftItems:[{id:`l1`,text:{en:`Rapid freezing`,ua:`Швидке заморожування`}},{id:`l2`,text:{en:`Freeze-thaw cycling`,ua:`Цикли заморожування-розморожування`}},{id:`l3`,text:{en:`Freezer burn`,ua:`Морозильний опік`}}],rightItems:[{id:`r2`,text:{en:`Can enlarge crystals and damage texture`,ua:`Можуть збільшувати кристали та псувати текстуру`}},{id:`r3`,text:{en:`Surface drying and quality loss`,ua:`Поверхневе висихання та втрата якості`}},{id:`r1`,text:{en:`Often forms smaller ice crystals`,ua:`Часто утворює менші кристали льоду`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-260-04`,theoryId:260,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Two identical purées are frozen, one in a shallow tray and one in a deep tub. What could improve texture retention?`,ua:`Два однакові пюре заморожують: одне в мілкому лотку, інше у глибокій ємності. Що може краще зберегти текстуру?`},explanation:{en:`A smaller thickness generally speeds heat removal and can reduce crystal damage.`,ua:`Менша товщина зазвичай прискорює відведення тепла та може зменшувати пошкодження кристалами.`},options:[{id:`a`,text:{en:`Freeze in a thin, suitable layer so it chills promptly`,ua:`Заморозити тонким шаром у належному посуді для швидкого охолодження`}},{id:`b`,text:{en:`Keep both warm before freezing`,ua:`Тримати обидва теплими перед заморожуванням`}},{id:`c`,text:{en:`Repeatedly thaw and refreeze the product`,ua:`Багаторазово розморожувати й знову заморожувати продукт`}}],answer:{optionIds:[`a`]}},{id:`cooking-260-05`,theoryId:260,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which factors affect frozen-food quality?`,ua:`Які чинники впливають на якість заморожених продуктів?`},explanation:{en:`Texture protection and microbial safety are separate goals.`,ua:`Збереження текстури та мікробіологічна безпечність — різні цілі.`},options:[{id:`a`,text:{en:`A belief that freezing makes raw meat safe without cooking`,ua:`Віра, що заморожування робить сире м’ясо безпечним без приготування`}},{id:`b`,text:{en:`Storage temperature stability`,ua:`Стабільність температури зберігання`}},{id:`c`,text:{en:`Freezing rate`,ua:`Швидкість заморожування`}},{id:`d`,text:{en:`Packaging against moisture loss`,ua:`Пакування для зменшення втрати вологи`}}],answer:{optionIds:[`c`,`b`,`d`]}}];var n={theoryId:260,exercises:i};export{n as default,i as exercises,a as theoryId};